
import type {
  VideoProject,
    ProjectCategory,
      VideoFormat,
        Scene,
          RenderSettings,
          } from './projectTypes'

          const STORAGE_KEY = 'motionforge_projects_v1'
          const LEGACY_STORAGE_KEY = 'motionforge_projects_v2'
          const MIGRATION_KEY = 'motionforge_v1_migration_completed'
          const DELETED_IDS_KEY = 'motionforge_deleted_project_ids_v1'

          function createId(): string {
            return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`
            }

            function getRenderSettings(format: VideoFormat): RenderSettings {
              const sizes: Record<VideoFormat, { width: number; height: number }> = {
                  vertical: { width: 1080, height: 1920 },
                      horizontal: { width: 1920, height: 1080 },
                          square: { width: 1080, height: 1080 },
                            }

                              return {
                                  ...sizes[format],
                                      format,
                                          fps: 30,
                                              output: 'mp4',
                                                }
                                                }

                                                function normalizeScene(scene: Partial<Scene>, index: number): Scene {
                                                  const duration =
                                                      typeof scene.duration === 'number' && scene.duration > 0
                                                            ? scene.duration
                                                                  : 5

                                                                    const startTime =
                                                                        typeof scene.startTime === 'number'
                                                                              ? scene.startTime
                                                                                    : 0

                                                                                      return {
                                                                                          id: String(scene.id ?? createId()),
                                                                                              order: typeof scene.order === 'number' ? scene.order : index + 1,
                                                                                                  title: scene.title ?? `مشهد ${index + 1}`,
                                                                                                      description: scene.description ?? '',
                                                                                                          narration: scene.narration,
                                                                                                              duration,
                                                                                                                  startTime,
                                                                                                                      endTime:
                                                                                                                            typeof scene.endTime === 'number'
                                                                                                                                    ? scene.endTime
                                                                                                                                            : startTime + duration,
                                                                                                                                                visualStyle: scene.visualStyle,
                                                                                                                                                    background: scene.background,
                                                                                                                                                        transition: scene.transition,
                                                                                                                                                            assets: Array.isArray(scene.assets) ? scene.assets : [],
                                                                                                                                                                layers: Array.isArray(scene.layers) ? scene.layers : [],
                                                                                                                                                                    notes: scene.notes,
                                                                                                                                                                      }
                                                                                                                                                                      }

                                                                                                                                                                      function normalizeProject(raw: Partial<VideoProject>): VideoProject {
                                                                                                                                                                        const format: VideoFormat =
                                                                                                                                                                            raw.format === 'horizontal' || raw.format === 'square'
                                                                                                                                                                                  ? raw.format
                                                                                                                                                                                        : 'vertical'

                                                                                                                                                                                          const scenes = Array.isArray(raw.scenes)
                                                                                                                                                                                              ? raw.scenes.map((scene, index) =>
                                                                                                                                                                                                      normalizeScene(scene, index),
                                                                                                                                                                                                            )
                                                                                                                                                                                                                : []

                                                                                                                                                                                                                  return {
                                                                                                                                                                                                                      id: String(raw.id ?? createId()),
                                                                                                                                                                                                                          name: raw.name ?? 'مشروع جديد',
                                                                                                                                                                                                                              idea: raw.idea ?? '',
                                                                                                                                                                                                                                  script: raw.script ?? '',
                                                                                                                                                                                                                                      category: raw.category ?? 'auto',
                                                                                                                                                                                                                                          status: raw.status ?? 'draft',
                                                                                                                                                                                                                                              format,
                                                                                                                                                                                                                                                  scenes,
                                                                                                                                                                                                                                                      assets: Array.isArray(raw.assets) ? raw.assets : [],
                                                                                                                                                                                                                                                          revisions: Array.isArray(raw.revisions) ? raw.revisions : [],
                                                                                                                                                                                                                                                              version:
                                                                                                                                                                                                                                                                    typeof raw.version === 'number' && raw.version > 0
                                                                                                                                                                                                                                                                            ? raw.version
                                                                                                                                                                                                                                                                                    : 1,
                                                                                                                                                                                                                                                                                        renderSettings: raw.renderSettings ?? getRenderSettings(format),
                                                                                                                                                                                                                                                                                            createdAt: raw.createdAt ?? new Date().toISOString(),
                                                                                                                                                                                                                                                                                                updatedAt: raw.updatedAt ?? new Date().toISOString(),
                                                                                                                                                                                                                                                                                                    description: raw.description ?? '',
                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                      function readStorage(key: string): VideoProject[] {
                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                            const raw = localStorage.getItem(key)
                                                                                                                                                                                                                                                                                                                if (!raw) return []

                                                                                                                                                                                                                                                                                                                    const parsed: unknown = JSON.parse(raw)
                                                                                                                                                                                                                                                                                                                        if (!Array.isArray(parsed)) return []

                                                                                                                                                                                                                                                                                                                            return parsed.map((item) =>
                                                                                                                                                                                                                                                                                                                                  normalizeProject(item as Partial<VideoProject>),
                                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                                        } catch {
                                                                                                                                                                                                                                                                                                                                            return []
                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                              function writeStorage(projects: VideoProject[]): void {
                                                                                                                                                                                                                                                                                                                                                localStorage.setItem(STORAGE_KEY, JSON.stringify(projects))
                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                function readDeletedIds(): Set<string> {
                                                                                                                                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                                                                                                                                      const raw = localStorage.getItem(DELETED_IDS_KEY)
                                                                                                                                                                                                                                                                                                                                                          if (!raw) return new Set()

                                                                                                                                                                                                                                                                                                                                                              const parsed: unknown = JSON.parse(raw)

                                                                                                                                                                                                                                                                                                                                                                  if (!Array.isArray(parsed)) return new Set()

                                                                                                                                                                                                                                                                                                                                                                      return new Set(parsed.map((id) => String(id)))
                                                                                                                                                                                                                                                                                                                                                                        } catch {
                                                                                                                                                                                                                                                                                                                                                                            return new Set()
                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                              function writeDeletedIds(ids: Set<string>): void {
                                                                                                                                                                                                                                                                                                                                                                                localStorage.setItem(
                                                                                                                                                                                                                                                                                                                                                                                    DELETED_IDS_KEY,
                                                                                                                                                                                                                                                                                                                                                                                        JSON.stringify(Array.from(ids)),
                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                          function mergeProjects(
                                                                                                                                                                                                                                                                                                                                                                                            current: VideoProject[],
                                                                                                                                                                                                                                                                                                                                                                                              legacy: VideoProject[],
                                                                                                                                                                                                                                                                                                                                                                                                deletedIds: Set<string>,
                                                                                                                                                                                                                                                                                                                                                                                                ): VideoProject[] {
                                                                                                                                                                                                                                                                                                                                                                                                  const merged = new Map<string, VideoProject>()

                                                                                                                                                                                                                                                                                                                                                                                                    // البيانات الحالية لها الأولوية على البيانات القديمة.
                                                                                                                                                                                                                                                                                                                                                                                                      for (const project of legacy) {
                                                                                                                                                                                                                                                                                                                                                                                                          if (!deletedIds.has(project.id)) {
                                                                                                                                                                                                                                                                                                                                                                                                                merged.set(project.id, project)
                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                        for (const project of current) {
                                                                                                                                                                                                                                                                                                                                                                                                                            if (!deletedIds.has(project.id)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                  merged.set(project.id, project)
                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                          return Array.from(merged.values()).sort(
                                                                                                                                                                                                                                                                                                                                                                                                                                              (a, b) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                    new Date(b.updatedAt).getTime() -
                                                                                                                                                                                                                                                                                                                                                                                                                                                          new Date(a.updatedAt).getTime(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            function migrateLegacyProjects(): VideoProject[] {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              const current = readStorage(STORAGE_KEY)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                const legacy = readStorage(LEGACY_STORAGE_KEY)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const deletedIds = readDeletedIds()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const merged = mergeProjects(current, legacy, deletedIds)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                      writeStorage(merged)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // نسجل اكتمال الترحيل حتى لا نعيد العملية كل مرة.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          localStorage.setItem(MIGRATION_KEY, 'true')

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return merged
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function getProjects(): VideoProject[] {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const migrationCompleted =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  localStorage.getItem(MIGRATION_KEY) === 'true'

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!migrationCompleted) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return migrateLegacyProjects()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const deletedIds = readDeletedIds()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return readStorage(STORAGE_KEY).filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  (project) => !deletedIds.has(project.id),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    export function createProject(input: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      name: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        idea: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          script?: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            category: ProjectCategory
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              format: VideoFormat
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }): VideoProject {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const now = new Date().toISOString()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const project = normalizeProject({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      id: createId(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          name: input.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              idea: input.idea,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  script: input.script ?? '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      category: input.category,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          format: input.format,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              status: 'draft',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  scenes: [],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      assets: [],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          revisions: [],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              version: 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  renderSettings: getRenderSettings(input.format),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      createdAt: now,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          updatedAt: now,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              description: '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const projects = getProjects()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    writeStorage([project, ...projects])

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return project
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      export function getAllProjects(): VideoProject[] {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return getProjects().sort(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            (a, b) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  new Date(b.updatedAt).getTime() -
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        new Date(a.updatedAt).getTime(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          export function getProjectById(id: string): VideoProject | null {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                getProjects().find((project) => project.id === id) ?? null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  export function updateProject(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    id: string,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      changes: Partial<VideoProject>,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ): VideoProject | null {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const projects = getProjects()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const index = projects.findIndex(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (project) => project.id === id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (index === -1) return null

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const current = projects[index]

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const updated = normalizeProject({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ...current,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ...changes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  id: current.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      createdAt: current.createdAt,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          updatedAt: new Date().toISOString(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              projects[index] = updated

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                writeStorage(projects)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return updated
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  export function deleteProject(id: string): boolean {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const projects = getProjects()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const exists = projects.some(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          (project) => project.id === id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!exists) return false

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const deletedIds = readDeletedIds()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  deletedIds.add(id)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // نحفظ علامة الحذف قبل تحديث قائمة المشاريع.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // حتى لا يعود المشروع من المخزن القديم.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        writeDeletedIds(deletedIds)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const filtered = projects.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (project) => project.id !== id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  writeStorage(filtered)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    export function saveProjectScenes(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      id: string,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        scenes: Scene[],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ): VideoProject | null {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return updateProject(id, { scenes })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          export function clearProjectStore(): void {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // يمسح المخزن الحالي فقط.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // لا يحذف المخزن القديم أو علامات الحذف.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                localStorage.removeItem(STORAGE_KEY)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                